const announceDialog = () => { if (browserDialog) send({ type: 'browser_dialog', requestId: browserDialog.requestId, kind: browserDialog.dialog.type(), message: browserDialog.dialog.message().slice(0, 4000) }); };
const stagedFiles = new Map<string, string>();
let depositPicker: { chooser: FileChooser; requestId: string; generation: number; navigation: number } | undefined;
const send = (value: unknown) => { if (socket?.readyState === WebSocket.OPEN) socket.send(JSON.stringify(value)); };
const extraHosts = (process.env.RIGHTS_VERIFIED_RESOURCE_HOSTS ?? '').split(',').filter(Boolean);
const hostAllowed = (host: string) => [...COPYRIGHT_PORTAL_HOSTS, 'www.copyright.gov', 'copyright.gov'].includes(host)
  || (paymentEnabled && (host === 'pay.gov' || host === 'www.pay.gov')) || extraHosts.includes(host);
const proxy = await createPortalProxy(hostAllowed);

async function attachPage(next: Page) {
  await cdp?.send('Page.stopScreencast').catch(() => {});
  await cdp?.detach().catch(() => {});
  page = next; cdp = await context!.newCDPSession(next);
  next.on('framenavigated', frame => {
    if (frame !== next.mainFrame()) return;
    fence.control = 'none'; depositPicker = undefined; fence.navigationGeneration++;
    send({ type: 'navigation', navigationGeneration: fence.navigationGeneration, viewportVersion: fence.viewportVersion });
    send({ type: 'control_ack', control: 'none', generation: fence.controlGeneration });
  });
  next.on('filechooser', chooser => {
    // Opening a picker never uploads implicitly. The artist selects the exact deposits.
    if (fence.control !== 'human' || !manifest) return;
    depositPicker = { chooser, requestId: randomUUID(), generation: fence.controlGeneration, navigation: fence.navigationGeneration };
    send({ type: 'deposit_request', requestId: depositPicker.requestId, multiple: chooser.isMultiple(), choices: manifest.works.map(work => ({ id: work.entityId, label: work.title })) });
  });
