export class CloudStorageService {
    /**
     * Compress image using HTML5 Canvas
     * No external dependencies required
     */
    static async compressImage(
        dataUri: string,
        options: ImageCompressionOptions = {}
    ): Promise<{ blob: Blob; dataUri: string }> {
        const {
            maxWidth = 2048,
            maxHeight = 2048,
            quality = 0.8,
            format = 'jpeg'
        } = options;

        return new Promise((resolve, reject) => {
            const img = new Image();

            img.onload = () => {
                // Calculate new dimensions while maintaining aspect ratio
                let { width, height } = img;
                if (width > maxWidth || height > maxHeight) {
                    const ratio = Math.min(maxWidth / width, maxHeight / height);
                    width *= ratio;
                    height *= ratio;
                }

                // Create canvas
                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;

                // Draw and compress
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    reject(new Error('Failed to get canvas context'));
                    return;
                }

                ctx.drawImage(img, 0, 0, width, height);

                // Convert to blob
                canvas.toBlob(
                    (blob) => {
                        if (!blob) {
                            reject(new Error('Failed to create blob'));
                            return;
                        }

                        // Convert blob to data URI for immediate display
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            resolve({
                                blob,
                                dataUri: reader.result as string
                            });
                        };
                        reader.readAsDataURL(blob);
                    },
                    format === 'png' ? 'image/png' : `image/${format}`,
                    quality
                );
            };

            img.onerror = () => reject(new Error('Failed to load image'));
            img.src = dataUri;
        });
    }

    /**
     * Generate thumbnail (300x300) for gallery display
     */
    static async generateThumbnail(dataUri: string): Promise<{ blob: Blob; dataUri: string }> {
        return this.compressImage(dataUri, {
            maxWidth: 300,
            maxHeight: 300,
            quality: 0.7,
            format: 'jpeg'
        });
