function artifactName(value: unknown): string {
    if (typeof value !== 'string' || !value || value.includes('\0') || value.includes('\\') ||
        path.basename(value) !== value || value === '.' || value === '..' ||
        !(value.endsWith('.md') || value.endsWith('.json')) || value === '.md' || value === '.json') {
