  const content = await room.captureAsArtist(room.control.state);
  assert.match(content.title, /spotify/i);
  const frame = await room.frame();
  assert.equal(frame.readUInt16BE(0), 0xffd8);
  const assignment = { requestId: 'test', stepId: 'research', agentId: 'marketing' };
  assert.equal(room.control.giveControl(assignment, room.control.state), true);
  const version = room.control.state;
  assert.equal((await room.readAsSpecialist(assignment, version)).url, content.url);
  const pending = room.readAsSpecialist(assignment, version);
  room.control.takeOver();
  await assert.rejects(pending, /control or the current page changed/);
  await room.navigateAsArtist('https://fonts.google.com/', room.control.state);
  assert.match((await room.captureAsArtist(room.control.state)).title, /google fonts/i);
  await room.historyAsArtist('back', room.control.state);
  assert.match((await room.captureAsArtist(room.control.state)).title, /spotify/i);
  await room.historyAsArtist('forward', room.control.state);
  await room.historyAsArtist('reload', room.control.state);
  assert.match((await room.captureAsArtist(room.control.state)).title, /google fonts/i);
  console.log('Chrome worker loaded Spotify and Google Fonts, captured a JPEG, rejected a queued specialist read after takeover, and passed back, forward, and reload.');
} finally { await room.close(); }
