  assert.equal(room.control.giveControl(assignment,room.control.state),true);
  const version = room.control.state;
  const result = await room.downloadSelectedFontAsSpecialist('Inter',assignment,version,new AbortController().signal);
  assert.equal(result.filename,'Inter.zip');
  assert.equal(result.bytes.readUInt32LE(0),0x04034b50);
  console.log(result.filename,result.bytes.length);
  const delayed = room.downloadSelectedFontAsSpecialist('Inter',assignment,version,new AbortController().signal);
  room.control.takeOver();
  await assert.rejects(delayed,/control or the current page changed/);
  console.log('Delayed specialist download rejected after artist takeover.');
} finally { await room.close(); }
EOF

