import assert from 'node:assert/strict';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { BoardroomSession } from './packages/rights-browser-worker/dist/boardroomSession.js';
const testDir=await mkdtemp(join(tmpdir(),'indii-font-check-'));
const room=await BoardroomSession.open('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome');
try {
  await room.navigateAsArtist('https://fonts.google.com/specimen/Inter',room.control.state);
  await room.page.getByRole('button',{name:'Get font',exact:true}).press('Enter',{timeout:8000});
  await room.page.getByText('Download all (1)',{exact:true}).waitFor({timeout:8000});
  const a={requestId:'test',stepId:'test',agentId:'creative'};
  assert.equal(room.control.giveControl(a,room.control.state),true);
  const result=await room.downloadSelectedFontAsSpecialist('Inter',a,room.control.state,new AbortController().signal);
  assert.equal(result.filename,'Inter.zip');
  const archive=join(testDir,result.filename); await writeFile(archive,result.bytes);
  execFileSync('unzip',['-tq',archive]);
  const entries=execFileSync('unzip',['-Z1',archive],{encoding:'utf8'});
  assert.match(entries,/Inter.*\.ttf/im);
  console.log('Verified '+result.filename+' ('+result.bytes.length+' bytes) contains Inter TTF files and passes ZIP integrity checks.');
  const delayed=room.downloadSelectedFontAsSpecialist('Inter',a,room.control.state,new AbortController().signal);
  room.control.takeOver(); await assert.rejects(delayed,/control or the current page changed/);
  console.log('Delayed download rejected after takeover.');
} finally { await room.close(); await rm(testDir,{recursive:true,force:true}); }
EOF

