                                addReference({
                                    id: `web-${secureUUIDv4()}`,
                                    name: page.title || page.url,
                                    type: 'url',
                                    value: page.url,
                                    prompt: page.text,
                                    origin: 'boardroom_browser',
                                });
                                setNotice('Page pinned to Swarm.');
